package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.time.temporal.ChronoUnit;

import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;

/** Reminds an OPEN or PENDING claim on the sheet's today. Refused for a claim in any other status, and
 *  for one already reminded on the sheet's today. With an escalation gap set, a claim never escalated whose
 *  previous reminder was at least that many days before the sheet's today is escalated by it. */
public class RemindClaim {
    public void remind(@Val Claim claim, SheetRepository sheets, SettingRepository settings, ClaimRepository claims)
            throws ClaimStatusException {
        if (!ClaimStatus.isOpen(claim.getStatus())) {
            throw new ClaimStatusException("A " + claim.getStatus() + " claim cannot be reminded");
        }
        LocalDate today = sheets.today(claim.getSheetId());
        if (today.toString().equals(claim.getReminded())) {
            throw new ClaimStatusException("The claim was already reminded on " + today);
        }
        String gap = settings.find(claim.getSheetId(), SettingRepository.ESCALATE_AFTER);
        if (gap != null && !gap.isEmpty() && claim.getReminded() != null
                && ChronoUnit.DAYS.between(LocalDate.parse(claim.getReminded()), today) >= Integer.parseInt(gap)
                && !claims.isEscalated(claim.getSheetId(), claim.getId())) {
            claim.setEscalating(true);
        }
        claim.setReminded(today.toString());
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;

public class SaveReminder {
    public void save(@Val Claim claim, ClaimRepository claims) {
        claims.updateReminded(claim);
        if (claim.isEscalating()) {
            claims.markEscalated(claim);
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Last write step: a reminder that went through, then its escalation, if it escalated the claim. */
public class RecordClaimReminded {
    public void record(@RequestParam(name = "by", required = false) String by,
            @Val Claim claim, PersonRepository people, Audit audit) {
        audit.record(RecordClaimStatus.line("REMIND", by, claim, people));
        if (claim.isEscalating()) {
            audit.record(RecordClaimStatus.line("ESCALATE", by, claim, people));
        }
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.period.PeriodClosedException;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.Role;
import net.officefloor.hq.app.setting.RoleRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Approves a PENDING claim: it becomes SETTLED, its due fixed at the figure it shows at that moment
 *  (the figure a statement bound it to, else its live figure, with its late charge on the sheet's
 *  today). Refused unless the user is a steward, and for the user who opened it or last edited it, and for one
 *  with no proofs whose due is above the proof threshold in force on its date. */
public class ApproveClaim {
    public void move(@RequestParam(name = "by", required = false) String by, @Val Claim claim,
            PersonRepository people, RateRepository rates, PeriodRepository periods,
            RoleRepository roles, SettingRepository settings, SheetRepository sheets)
            throws ClaimStatusException, PeriodClosedException {
        periods.requireOpen(claim.getSheetId(), claim.getDueBy());
        String user = by == null ? "" : by;
        if (!ClaimStatus.PENDING.name().equals(claim.getStatus())) {
            throw new ClaimStatusException("A " + claim.getStatus() + " claim cannot be approved");
        }
        if (!Role.STEWARD.equals(roles.roleOf(claim.getSheetId(), user))) {
            throw new ClaimStatusException("Only a steward can approve a claim");
        }
        if (claim.getOpenedBy() != null && claim.getOpenedBy().equals(user)) {
            throw new ClaimStatusException("The user who opened a claim cannot approve it");
        }
        if (claim.getEditedBy() != null && claim.getEditedBy().equals(user)) {
            throw new ClaimStatusException("The user who last edited a claim cannot approve it");
        }
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        Rate rate = person == null ? null : rates.find(claim.getSheetId(), person.gradeOn(claim.getDate()),
                LocalDate.parse(claim.getDate()), claim.getId());
        Dues.Late late = settings.late(claim.getSheetId(), sheets.today(claim.getSheetId()));
        String due = Dues.shown(claim, rate == null ? null : Dues.of(claim.getAmount(), rate.pct(),
                late.rounding(claim.getRoundDate())), settings.floor(claim.getSheetId()).on(claim.getDate()), late);
        SettleClaim.requireProof(claim, person, due, settings);
        claim.setStatus(ClaimStatus.PENDING.moveTo(ClaimStatus.SETTLED).name());
        claim.setSettledDue(due);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Last write step of an approval: CLAIM_APPROVED with the due it was fixed at. */
public class RecordClaimApproved {
    public void record(@RequestParam(name = "by", required = false) String by,
            @Val Claim claim, PersonRepository people, Audit audit) {
        audit.record(RecordClaimStatus.line("CLAIM_APPROVED", by, claim, people) + RecordClaimStatus.due(claim));
    }
}

